<script lang="ts">
  import { onMount } from 'svelte';
  import { api, type Dataset, type Dashboard } from '$lib/api';
  import Chart from '$lib/Chart.svelte';
  let data = $state<Dashboard | null>(null);
  let dataset = $state<Dataset | null>(null);
  let error = $state('');
  let seed = $state('42');
  const percent = (v: number | null) => v === null ? 'Não verificado' : `${(100*v).toFixed(1)}%`;
  const names: Record<string,string> = { random: 'Aleatório', rule_based: 'Regras fixas', q_learning: 'Q-Learning' };
  onMount(async () => { try { [data, dataset] = await Promise.all([api<Dashboard>('model/metrics'), api<Dataset>('dataset/info')]); seed = String(data.training.selected_seed); } catch(e) { error = String(e); } });
</script>
<section class="intro"><div><p class="eyebrow">02 / EVIDÊNCIA EXPERIMENTAL</p><h1>Aprendizado em números.<br/><span>Limites à vista.</span></h1><p class="lead">Três políticas, os mesmos exemplos de teste. Métricas calculadas a partir de execuções registradas.</p></div><aside class="scope"><span class="dot"></span> Experimento reproduzível<p>Validação de propriedade SQL local.<br/>Equivalência funcional não verificada.</p></aside></section>
{#if error}<p class="error" role="alert">{error}</p>{:else if !data || !dataset}<p class="notice" aria-live="polite">Carregando artefatos do experimento…</p>{:else}
  <div class="stats"><div><span>Dataset oficial</span><strong>{dataset.total.toLocaleString('pt-BR')}</strong><small>OWASP Benchmark Python {dataset.version}</small></div><div><span>Casos no escopo</span><strong>{dataset.selected}</strong><small>3 categorias CWE</small></div><div><span>Episódios por semente</span><strong>{data.training.runs[0].episodes.toLocaleString('pt-BR')}</strong><small>{data.training.runs.length} sementes independentes</small></div><div><span>Exemplos de teste</span><strong>{dataset.splits.test.count}</strong><small>Separação por grupos de fluxo</small></div></div>
  <div class="section-heading"><h2>Evolução do treinamento</h2><label>Semente <select bind:value={seed}>{#each data.training.runs as run}<option value={String(run.seed)}>{run.seed}</option>{/each}</select></label></div>
  <section class="panel"><Chart rows={data.curves[seed] || []} metric="reward" title="Recompensa média · janela de 100 episódios"/><div class="grid md:grid-cols-2"><Chart rows={data.curves[seed] || []} metric="epsilon" title="Exploração · epsilon"/><Chart rows={data.curves[seed] || []} metric="validated" title="Episódios com correção validada · janela de 100"/></div></section>
  <section class="panel mt-6"><div class="panel-heading"><h2>Comparação no conjunto de teste</h2><span class="badge">Semente {seed}</span></div><div class="table-scroll"><table><thead><tr><th>Política</th><th>Correções / positivos</th><th>Correções / tratáveis</th><th>Alterações indevidas</th><th>Ações médias</th><th>Recompensa média</th></tr></thead><tbody>{#each data.evaluation.experiments.filter(e => String(e.seed) === seed) as exp}<tr><td><strong>{names[exp.policy]}</strong></td><td>{percent(exp.metrics.validated_correction_rate)} ({exp.metrics.validated}/{exp.metrics.positives})</td><td>{percent(exp.metrics.treatable_correction_rate)}</td><td>{percent(exp.metrics.unnecessary_change_rate)}</td><td>{exp.metrics.mean_actions.toFixed(2)}</td><td>{exp.metrics.mean_reward.toFixed(2)}</td></tr>{/each}</tbody></table></div><p class="notice">Regressões funcionais e sucesso completo: não verificados. A correção validada atesta somente a propriedade SQL local. O teste contém apenas um SQL positivo.</p></section>
  <div class="grid lg:grid-cols-2 gap-6 mt-6"><section class="panel"><div class="panel-heading"><h2>Correções por categoria</h2></div><div class="p-6 space-y-6">{#each data.evaluation.experiments.filter(e => String(e.seed) === seed) as exp}<div><h3>{names[exp.policy]}</h3>{#each Object.entries(exp.by_cwe) as [cwe,m]}<div class="bar-row"><span>CWE-{cwe}</span><div class="bar-track"><div style={`width:${(m.validated_correction_rate || 0)*100}%`}></div></div><span>{m.validated}/{m.positives}</span></div>{/each}</div>{/each}</div></section>
  <section class="panel"><div class="panel-heading"><h2>Distribuição das ações</h2></div><div class="p-6 space-y-6">{#each data.evaluation.experiments.filter(e => String(e.seed) === seed) as exp}<div><h3>{names[exp.policy]}</h3>{#each Object.entries(exp.metrics.actions) as [action,count]}<div class="action-row"><code>{action}</code><span>{count}</span></div>{/each}</div>{/each}</div></section></div>
  <section class="panel mt-6"><div class="panel-heading"><h2>Origem e protocolo</h2><a href="https://github.com/OWASP-Benchmark/BenchmarkPython">Repositório OWASP ↗</a></div><div class="p-6"><p>{dataset.dataset} · versão {dataset.version}</p><p class="mono break-all">Commit: {dataset.commit}</p><p class="mt-3">Treinamento: {dataset.splits.train.count} · Validação: {dataset.splits.validation.count} · Teste: {dataset.splits.test.count}</p><p class="notice">Agrupamento heurístico por AST do fluxo. Não comprova ausência de toda similaridade. O escopo pequeno não sustenta generalização para reparo de código em produção.</p><details><summary>Distribuição original por CWE e rótulo</summary><div class="distribution">{#each Object.entries(dataset.distribution) as [key,count]}<div><span>{key}</span><strong>{count}</strong></div>{/each}</div></details><details><summary>Hiperparâmetros e recompensas</summary><pre>{JSON.stringify(data.training.runs[0].config, null, 2)}</pre></details></div></section>
{/if}
